  "source": "def summarize_values(values):
    n = len(values)
    if n == 0:
        return 0
    contrib = []
    for i in range(n):
        x = values[i]
        p = 2*x + 1*x*x + 1*x*x*x
        g = 1
        if i == 0:
            extra = 0
        else:
            extra = g * x * values[i-1]
        contrib.append(p + extra)
    for _ in range(3):
        for i in range(1, n):
            contrib[i] = contrib[i] + contrib[i-1]
    return contrib[-1]

def readout(summary):
    return summary

def investigate(context, acquire):
    return readout(summarize_values(context["values"]))
